1	<?php
2	
3	namespace Bootstrap;
4	
5	final class UploadPathRegistry
6	{
7	    /** @var array<string, string> */
8	    private $values = [];
9	
10	    public function __construct(string $projectRoot, string $webBase)
11	    {
12	        $normalizedProjectRoot = str_replace('\\', '/', rtrim($projectRoot, '/\\'));
13	        $normalizedWebBase = rtrim($webBase, '/');
14	        $baseDirectory = $normalizedProjectRoot . '/uploads';
15	        $baseWebDirectory = ($normalizedWebBase !== '' ? $normalizedWebBase : '') . '/uploads';
16	
17	        $this->values = [
18	            'UPLOAD_DIR_BASE' => $baseDirectory,
19	            'UPLOAD_WDIR_BASE' => $baseWebDirectory,
20	            'UPLOAD_DIR_POPUP' => $baseDirectory . '/popups',
21	            'UPLOAD_WDIR_POPUP' => $baseWebDirectory . '/popups',
22	            'UPLOAD_DIR_CLIENTS' => $baseDirectory . '/clients',
23	            'UPLOAD_WDIR_CLIENTS' => $baseWebDirectory . '/clients',
24	            'UPLOAD_DIR_BOARD' => $baseDirectory . '/board',
25	            'UPLOAD_WDIR_BOARD' => $baseWebDirectory . '/board',
26	            'UPLOAD_SITEINFO_DIR_LOGO' => $baseDirectory . '/logo',
27	            'UPLOAD_SITEINFO_WDIR_LOGO' => $baseWebDirectory . '/logo',
28	            'UPLOAD_META_DIR' => $baseDirectory . '/meta',
29	            'UPLOAD_META_WDIR' => $baseWebDirectory . '/meta',
30	            'UPLOAD_DIR_EMPLOYMENT' => $baseDirectory . '/employment',
31	            'UPLOAD_WDIR_EMPLOYMENT' => $baseWebDirectory . '/employment',
32	            'UPLOAD_DIR_ADMISSION' => $baseDirectory . '/admission',
33	            'UPLOAD_WDIR_ADMISSION' => $baseWebDirectory . '/admission',
34	            'UPLOAD_DIR_REQUEST' => $baseDirectory . '/request',
35	            'UPLOAD_WDIR_REQUEST' => $baseWebDirectory . '/request',
36	            'UPLOAD_DIR_WORKS' => $baseDirectory . '/works',
37	            'UPLOAD_WDIR_WORKS' => $baseWebDirectory . '/works',
38	        ];
39	    }
40	
41	    public function get(string $key, string $default = ''): string
42	    {
43	        return $this->values[$key] ?? $default;
44	    }
45	
46	    public function all(): array
47	    {
48	        return $this->values;
49	    }
50	}
