2	
3	include_once "../../../../inc/lib/base.class.php";
4	include_once "../../../lib/auth/admin.check.ajax.php";
5	$role->requireLogin();
6	$role->requireCanModify();
7	
8	$root = rtrim($NO_PROJECT_ROOT, '/\\');
9	$uploadDir = $UPLOAD_DIR_BOARD;
10	$uploadBaseDir = $UPLOAD_WDIR_BOARD;
11	$maxFileSize = 20 * 1024 * 1024; // 20MB
12	
13	// 서버에서 고정 관리하는 업로드 허용 확장자 화이트리스트
14	$allowed_ext = [
15	    'jpg', 'jpeg', 'png', 'gif', 'webp',
16	    'pdf', 'zip',
17	    'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'hwp',
18	    'txt', 'mp4', 'mov', 'avi'
19	];
20	
21	if (!is_dir($uploadDir) && !mkdir($uploadDir, 0755, true) && !is_dir($uploadDir)) {
22	    echo json_encode(['success' => false, 'filename' => null, 'error' => '업로드 경로 생성 실패']);
23	    exit;
24	}
25	
26	if (!is_writable($uploadDir)) {
27	    echo json_encode(['success' => false, 'filename' => null, 'error' => '업로드 경로 권한 오류']);
28	    exit;
29	}
30	
31	$method = $_POST['_method'] ?? $_SERVER['REQUEST_METHOD'];
32	$method = strtolower($method);
33	
34	$jsonData = ['success' => false, 'filename' => null];
35	
36	if ($method === 'post') {
37	    $ext = isset($_POST['extension']) ? strtolower(trim((string)$_POST['extension'])) : '';
38	
39	    if (isset($_FILES['file']) && $_FILES['file']['error'] === UPLOAD_ERR_OK) {
40	        $tmpName = $_FILES['file']['tmp_name'];
41	        $realExt = strtolower(pathinfo($_FILES['file']['name'], PATHINFO_EXTENSION));
42	        $fileSize = (int)($_FILES['file']['size'] ?? 0);
43	
44	        if ($ext === '' || !in_array($ext, $allowed_ext, true)) {
45	            $jsonData = ['success' => false, 'filename' => null, 'error' => '허용되지 않는 확장자입니다.'];
46	        } elseif ($realExt !== $ext || !in_array($realExt, $allowed_ext, true)) {
47	            $jsonData = ['success' => false, 'filename' => null, 'error' => '파일 확장자가 일치하지 않거나 허용되지 않습니다.'];
48	        } elseif ($fileSize <= 0 || $fileSize > $maxFileSize) {
49	            $jsonData = ['success' => false, 'filename' => null, 'error' => '파일 크기 제한을 초과했습니다.'];
50	        } elseif (!is_uploaded_file($tmpName)) {
51	            $jsonData = ['success' => false, 'filename' => null, 'error' => '유효한 업로드 파일이 아닙니다.'];
52	        } else {
53	            $mimeType = '';
54	            if (function_exists('finfo_open')) {
55	                $finfo = finfo_open(FILEINFO_MIME_TYPE);
56	                if ($finfo !== false) {
57	                    $mimeType = (string)finfo_file($finfo, $tmpName);
58	                    finfo_close($finfo);
59	                }
60	            } elseif (function_exists('mime_content_type')) {
61	                $mimeType = (string)mime_content_type($tmpName);
62	            }
63	
64	            $blockedMimeKeywords = ['php', 'html', 'javascript', 'x-sh', 'x-httpd'];
65	            $isBlockedMime = false;
66	            foreach ($blockedMimeKeywords as $keyword) {
67	                if ($mimeType !== '' && stripos($mimeType, $keyword) !== false) {
68	                    $isBlockedMime = true;
69	                    break;
70	                }
71	            }
72	
73	            if ($isBlockedMime) {
74	                $jsonData = ['success' => false, 'filename' => null, 'error' => '허용되지 않는 파일 형식입니다.'];
75	            } else {
76	                $newName = uniqid('', true) . '.' . $ext;
77	                $uploadFile = $uploadDir . '/' . $newName;
78	
79	                if (move_uploaded_file($tmpName, $uploadFile)) {
80	                    $jsonData = [
81	                        'filename' => $uploadBaseDir . '/' . $newName,
82	                        'success' => true,
83	                    ];
84	                } else {
85	                    $jsonData = ['success' => false, 'filename' => null, 'error' => '업로드 실패'];
86	                }
87	            }
88	        }
89	    } else {
90	        $jsonData = [
91	            'filename' => null,
92	            'success' => false,
93	            'error' => isset($_FILES['file']) ? 'File upload error' : '파일이 없습니다.',
94	        ];
95	    }
96	}
97	
98	if ($method === 'delete') {
99	    $link = trim((string)($_POST['link'] ?? ''), '/');
100	    $targetPath = $link !== '' ? realpath($root . '/' . $link) : false;
101	    $uploadDirReal = realpath($uploadDir);
102	    $isInsideUploadDir = $targetPath && $uploadDirReal && strpos($targetPath, $uploadDirReal) === 0;
103	
104	    if ($link !== '' && strpos($link, 'uploads/board/') === 0 && $isInsideUploadDir && file_exists($targetPath)) {
105	        $result = unlink($targetPath);
106	        $jsonData = ['success' => (bool)$result];
107	    } else {
108	        $jsonData = ['success' => false];
109	    }
110	}
111	
112	echo json_encode($jsonData);
