29	
30	        if ($linkRaw !== '' && $data['link_url'] === null) {
31	            $validator->require('link_url', '', '링크 URL');
32	        }
33	
34	        $upload = imageUpload($uploadPath, $_FILES['thumb_image'] ?? []);
35	        $data['thumb_image'] = !empty($upload['saved']) ? $upload['saved'] : null;
36	
37	        if ($validator->fails()) {
38	            admin_json_validator_fail($validator);
39	        }
40	
41	        ClientModel::bumpSortNosOnInsert();
