45	        admin_json_send((bool) $result, $result ? '클라이언트가 등록되었습니다.' : '등록에 실패했습니다.');
46	    }
47	
48	    if ($mode === 'update') {
49	        $id = (int) ($input['id'] ?? 0);
50	        if ($id <= 0) {
51	            throw new Exception('유효한 ID가 없습니다.');
52	        }
53	
54	        $existing = ClientModel::find($id);
55	        if (!$existing) {
56	            admin_json_send(false, '데이터를 찾을 수 없습니다.');
57	        }
58	
59	        $linkRaw = trim($input['link_url'] ?? '');
60	        $data = [
61	            'title' => trim($input['title'] ?? ''),
62	            'is_visible' => (int) ($input['is_visible'] ?? 1) ? 1 : 0,
63	            'link_url' => $linkRaw === '' ? null : (safe_url($linkRaw, ['http', 'https'], true) ?: null),
64	            'sort_no' => (int) $existing['sort_no'],
65	        ];
66	
67	        $validator->require('title', $data['title'], '제목');
68	
69	        if ($linkRaw !== '' && $data['link_url'] === null) {
70	            $validator->require('link_url', '', '링크 URL');
71	        }
72	
73	        $hasNewThumb = !empty($_FILES['thumb_image'])
74	            && isset($_FILES['thumb_image']['error'])
75	            && $_FILES['thumb_image']['error'] === UPLOAD_ERR_OK;
76	
77	        if ($hasNewThumb) {
78	            if (!empty($existing['thumb_image']) && file_exists($uploadPath . '/' . $existing['thumb_image'])) {
79	                imageDelete($uploadPath . '/' . $existing['thumb_image']);
80	            }
81	            $up = imageUpload($uploadPath, $_FILES['thumb_image']);
82	            if (!empty($up['saved'])) {
83	                $data['thumb_image'] = $up['saved'];
84	            }
85	        }
86	
87	        if ($validator->fails()) {
88	            admin_json_validator_fail($validator);
89	        }
90	
91	        $result = ClientModel::update($id, $data);
92	        admin_json_send((bool) $result, $result ? '수정되었습니다.' : '수정에 실패했습니다.');
93	    }
94	
95	    if ($mode === 'delete') {
96	        $id = (int) ($input['id'] ?? 0);
97	        if ($id <= 0) {
98	            throw new Exception('유효한 ID가 없습니다.');
99	        }
100	
101	        $existing = ClientModel::find($id);
102	        if ($existing && !empty($existing['thumb_image']) && file_exists($uploadPath . '/' . $existing['thumb_image'])) {
103	            imageDelete($uploadPath . '/' . $existing['thumb_image']);
104	        }
105	
106	        $result = ClientModel::delete($id);
107	        admin_json_send((bool) $result, $result ? '삭제되었습니다.' : '삭제에 실패했습니다.');
108	    }
109	
110	    if ($mode === 'delete_array') {
111	        $ids = json_decode($input['ids'] ?? '[]', true);
112	        if (!is_array($ids) || count($ids) === 0) {
113	            throw new Exception('삭제할 항목이 선택되지 않았습니다.');
114	        }
115	
116	        foreach ($ids as $cid) {
117	            $row = ClientModel::find((int) $cid);
118	            if ($row && !empty($row['thumb_image']) && file_exists($uploadPath . '/' . $row['thumb_image'])) {
119	                imageDelete($uploadPath . '/' . $row['thumb_image']);
120	            }
121	        }
122	
123	        $result = ClientModel::deleteMultiple($ids);
124	        admin_json_send((bool) $result, $result ? '선택 항목이 삭제되었습니다.' : '삭제에 실패했습니다.');
125	    }
126	
127	    if ($mode === 'sort') {
128	        $id = (int) ($input['id'] ?? 0);
129	        $newNo = (int) ($input['new_no'] ?? 0);
130	        admin_json_handle_sort_reorder(
131	            'ClientModel',
132	            $id,
133	            $newNo,
134	            static function (array $currentData, int $sortNo): array {
135	                return [
