137	                    'is_visible' => (int) $currentData['is_visible'],
138	                    'link_url' => $currentData['link_url'],
139	                    'thumb_image' => $currentData['thumb_image'],
140	                    'sort_no' => $sortNo,
141	                ];
142	            }
143	        );
144	    }
145	
146	    admin_json_send(false, '유효하지 않은 요청입니다.');
147	} catch (Exception $e) {
148	    admin_json_server_error($e);
149	}
