9	
10	/**
11	 * @param array<string, mixed> $input
12	 * @param array<string, mixed> $files
13	 * @return array<string, mixed>
14	 */
15	function works_admin_collect_payload(array $input, array $files, string $uploadPath, ?array $existing = null): array
16	{
17	    global $work_service_types, $work_category_types, $work_price_types, $work_visibility_types, $work_notice_types, $work_award_types;
18	
19	    $serviceMap = is_array($work_service_types ?? null) ? $work_service_types : [];
20	    $categoryMap = is_array($work_category_types ?? null) ? $work_category_types : [];
21	    $validPrice = [0 => true];
22	    foreach (array_keys(is_array($work_price_types ?? null) ? $work_price_types : []) as $pk) {
23	        $validPrice[(int) $pk] = true;
24	    }
25	
26	    $title = trim((string) ($input['title'] ?? ''));
27	    $subTitle = trim((string) ($input['sub_title'] ?? ''));
28	    $isAwarded = strtoupper(trim((string) ($input['is_awarded'] ?? 'N'))) === 'Y' ? 'Y' : 'N';
29	    $awardTypeRaw = (int) ($input['award_type'] ?? 0);
30	    $awardMap = is_array($work_award_types ?? null) ? $work_award_types : [];
31	    $awardType = null;
32	    if ($isAwarded === 'Y' && isset($awardMap[$awardTypeRaw])) {
33	        $awardType = $awardTypeRaw;
34	    }
35	
36	    $awardDetailVal = null;
37	    if ($isAwarded === 'Y') {
38	        $ad = trim((string) ($input['award_detail'] ?? ''));
39	        if ($ad !== '') {
40	            $awardDetailVal = mb_substr($ad, 0, 512);
41	        }
42	    }
43	
44	    $price = (int) ($input['price'] ?? 0);
45	    if (!isset($validPrice[$price])) {
46	        $price = 0;
47	    }
48	
49	    $isVisible = (int) ($input['is_visible'] ?? 1);
50	    if (!isset($work_visibility_types[$isVisible])) {
51	        $isVisible = 1;
52	    }
53	    $isNotice = (int) ($input['is_notice'] ?? 1);
54	    if (!isset($work_notice_types[$isNotice])) {
55	        $isNotice = 1;
56	    }
57	
58	    $serviceIds = [];
59	    if (!empty($input['services']) && is_array($input['services'])) {
60	        foreach ($input['services'] as $v) {
61	            $serviceIds[] = (int) $v;
62	        }
63	    }
64	    $categoryIds = [];
65	    if (!empty($input['category']) && is_array($input['category'])) {
66	        foreach ($input['category'] as $v) {
67	            $categoryIds[] = (int) $v;
68	        }
69	    }
70	
71	    $servicesJson = works_admin_json_int_subset($serviceIds, $serviceMap);
72	    $categoryJson = works_admin_json_int_subset($categoryIds, $categoryMap);
73	
74	    $linkRaw = trim((string) ($input['link_url'] ?? ''));
75	    $linkUrl = $linkRaw === '' ? null : (safe_url($linkRaw, ['http', 'https'], true) ?: null);
76	
77	    $client = trim((string) ($input['client'] ?? ''));
78	    $clientVal = $client === '' ? null : $client;
79	
80	    $overview = trim((string) ($input['overview'] ?? ''));
81	    $contents = trim((string) ($input['contents'] ?? ''));
82	    $overviewVal = $overview === '' ? null : $overview;
83	    $contentsVal = $contents === '' ? null : $contents;
84	
85	    $tagJson = works_admin_lines_to_json((string) ($input['tag_lines'] ?? ''));
86	
87	    $sortNo = $existing !== null
88	        ? (int) ($existing['sort_no'] ?? 0)
89	        : 0;
90	
91	    $thumb = $existing !== null ? ($existing['thumb_image'] ?? null) : null;
92	    $att = [
93	        1 => $existing !== null ? ($existing['file_attach1'] ?? null) : null,
94	        2 => $existing !== null ? ($existing['file_attach2'] ?? null) : null,
95	        3 => $existing !== null ? ($existing['file_attach3'] ?? null) : null,
96	        4 => $existing !== null ? ($existing['file_attach4'] ?? null) : null,
97	        5 => $existing !== null ? ($existing['file_attach5'] ?? null) : null,
98	    ];
99	
100	    $hasThumb = !empty($files['thumb_image'])
101	        && isset($files['thumb_image']['error'])
102	        && (int) $files['thumb_image']['error'] === UPLOAD_ERR_OK;
103	    if ($hasThumb) {
104	        $up = imageUpload(
105	            $uploadPath,
106	            $files['thumb_image'],
107	            (string) ($existing !== null ? ($existing['thumb_image'] ?? '') : ''),
108	            false
109	        );
110	        if (!empty($up['saved'])) {
111	            $thumb = $up['saved'];
112	        }
113	    }
114	
115	    for ($i = 1; $i <= 5; $i++) {
116	        $key = 'file_attach' . $i;
117	        $has = !empty($files[$key])
118	            && isset($files[$key]['error'])
119	            && (int) $files[$key]['error'] === UPLOAD_ERR_OK;
120	        if ($has) {
121	            $up = imageUpload(
122	                $uploadPath,
123	                $files[$key],
124	                (string) ($existing !== null ? ($existing['file_attach' . $i] ?? '') : ''),
125	                false
126	            );
127	            if (!empty($up['saved'])) {
128	                $att[$i] = $up['saved'];
129	            }
130	        }
131	    }
132	
133	    $prevVideoFile = $existing !== null ? works_admin_first_stored_video_filename($existing['video'] ?? null) : '';
134	    $videoJson = $existing !== null ? ($existing['video'] ?? null) : null;
135	    $videoClear = !empty($input['video_clear']) && (int) $input['video_clear'] === 1;
136	    $hasVideoUpload = !empty($files['video_file'])
137	        && isset($files['video_file']['error'])
138	        && (int) $files['video_file']['error'] === UPLOAD_ERR_OK;
139	    if ($hasVideoUpload) {
140	        $prevForReplace = $prevVideoFile !== '' ? $prevVideoFile : null;
141	        $saved = works_admin_video_upload($uploadPath, $files['video_file'], $prevForReplace);
142	        if ($saved !== '') {
143	            $videoJson = json_encode([$saved], JSON_UNESCAPED_UNICODE);
144	        }
145	    } elseif ($videoClear) {
146	        if ($prevVideoFile !== '' && is_file($uploadPath . '/' . $prevVideoFile)) {
147	            @unlink($uploadPath . '/' . $prevVideoFile);
148	        }
149	        $videoJson = null;
150	    }
151	
152	    return [
153	        'title' => $title,
154	        'sub_title' => $subTitle === '' ? null : $subTitle,
155	        'is_awarded' => $isAwarded,
156	        'award_type' => $awardType,
157	        'award_detail' => $awardDetailVal,
158	        'price' => $price,
159	        'thumb_image' => $thumb,
160	        'is_visible' => $isVisible,
161	        'is_notice' => $isNotice,
162	        'services' => $servicesJson,
163	        'client' => $clientVal,
164	        'category' => $categoryJson,
165	        'link_url' => $linkUrl,
166	        'video' => $videoJson,
167	        'overview' => $overviewVal,
168	        'contents' => $contentsVal,
169	        'file_attach1' => $att[1],
170	        'file_attach2' => $att[2],
171	        'file_attach3' => $att[3],
172	        'file_attach4' => $att[4],
173	        'file_attach5' => $att[5],
174	        'tag' => $tagJson,
175	        'sort_no' => $sortNo,
176	    ];
177	}
178	
179	$role->requireLogin();
180	$role->requireCanModify();
181	
182	if (($_SERVER['REQUEST_METHOD'] ?? '') === 'GET') {
183	    $getMode = (string) ($_GET['mode'] ?? '');
184	    if ($getMode === 'rebalance_sort' || $getMode === 'restore_works_sort') {
185	        $guardKey = function_exists('env_string') ? env_string('WORKS_SORT_REBALANCE_KEY', '') : '';
186	        if ($guardKey !== '' && (string) ($_GET['key'] ?? '') !== $guardKey) {
187	            header('Content-Type: application/json; charset=utf-8');
188	            http_response_code(403);
189	            echo json_encode(['ok' => false, 'message' => 'WORKS_SORT_REBALANCE_KEY 가 일치하지 않습니다.'], JSON_UNESCAPED_UNICODE);
190	
191	            exit;
192	        }
193	        header('Content-Type: application/json; charset=utf-8');
194	        try {
195	            if ($getMode === 'restore_works_sort') {
196	                if ((string) ($_GET['confirm'] ?? '') !== '1') {
197	                    echo json_encode([
198	                        'ok' => false,
199	                        'message' => '직전 스냅샷 복원은 confirm=1 이 필요합니다.',
200	                    ], JSON_UNESCAPED_UNICODE);
201	                    exit;
202	                }
203	                $n = WorkModel::restoreSortNosFromUndo();
204	                echo json_encode(['ok' => true, 'restored_rows' => $n], JSON_UNESCAPED_UNICODE);
