326	if (!function_exists('safe_url')) {
327	    function safe_url(string $url, array $allowedSchemes = ['http', 'https'], bool $returnEmpty = false): ?string
328	    {
329	        $url = trim($url);
330	        if ($url === '') {
331	            return $returnEmpty ? '' : null;
332	        }
333	
334	        $scheme = strtolower((string) (parse_url($url, PHP_URL_SCHEME) ?? ''));
335	        if (!in_array($scheme, $allowedSchemes, true)) {
336	            return $returnEmpty ? '' : null;
337	        }
338	
339	        return filter_var($url, FILTER_VALIDATE_URL) !== false ? $url : ($returnEmpty ? '' : null);
340	    }
341	}
