343	if (!function_exists('sanitize_html_fragment')) {
344	    function sanitize_html_fragment(string $html): string
345	    {
346	        if ($html === '') {
347	            return '';
348	        }
349	
350	        $allowed = '<p><br><b><strong><i><em><u><ul><ol><li><a><span><h1><h2><h3><h4><h5><h6>';
351	        $stripped = strip_tags($html, $allowed);
352	        $stripped = preg_replace('/\s*on\w+\s*=\s*("[^"]*"|\'[^\']*\')/i', '', $stripped) ?? $stripped;
353	        $stripped = preg_replace('/\s*javascript\s*:/i', '', $stripped) ?? $stripped;
354	
355	        return $stripped;
356	    }
357	}
